public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Generate a complete bipartite graph
    int numVertices = target.getNumVertices();
    if (numVertices < 2) {
        throw new IllegalArgumentException("At least two vertices are required to form a bipartite graph.");
    }

    int half = numVertices / 2;
    for (int i = 0; i < half; i++) {
        resultMap.put("U_" + i, target.getVertex(i));
    }

    for (int i = half; i < numVertices; i++) {
        resultMap.put("V_" + (i - half), target.getVertex(i));
    }

    for (int i = 0; i < half; i++) {
        for (int j = half; j < numVertices; j++) {
            target.addEdge(resultMap.get("U_" + i), resultMap.get("V_" + (j - half)));
        }
    }
}

