protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edges = new ArrayList<>(tour);
    if (edges.isEmpty()) {
        return graph.createPath();
    }
    V startVertex = edges.get(0).getTarget();
    List<V> vertices = new ArrayList<>();
    vertices.add(startVertex);
    for (E edge : edges) {
        if (!edge.getSource().equals(startVertex)) {
            throw new IllegalArgumentException("Edges do not form a valid tour");
        }
        vertices.add(edge.getTarget());
        startVertex = edge.getTarget();
    }
    if (!graph.containsVertex(vertices.get(vertices.size() - 1))) {
        throw new IllegalArgumentException("Tour contains vertices not in the graph");
    }
    List<E> pathEdges = new ArrayList<>();
    for (int i = 0; i < vertices.size(); i++) {
        if (i < vertices.size() - 1) {
            pathEdges.add(graph.findEdge(vertices.get(i), vertices.get(i + 1)));
        } else {
            pathEdges.add(graph.findEdge(vertices.get(i), vertices.get(0)));
        }
    }
    return graph.createPath(pathEdges);
}

