public Mappings diffStructure(String tableName, Mappings mappings) {
    if (tableName == null || tableName.isEmpty()) {
        throw new IllegalArgumentException("Table name cannot be null or empty");
    }
    if (mappings == null) {
        throw new IllegalArgumentException("Mappings cannot be null");
    }
    Mappings historyMappings = getIndexesForTableCreateIfEmpty(tableName);
    if (historyMappings == null) {
        throw new IllegalStateException("History mappings not found for table: " + tableName);
    }
    Mappings diffMappings = new Mappings();
    for (String field : historyMappings.getFields()) {
        if (!mappings.containsField(field) && !field.equals("_source")) {
            diffMappings.addField(field);
        }
    }
    return diffMappings;
}

