    try {
        int count = 1; // Start with 1 because the descriptor itself is popped if it's a method descriptor
        if (descriptor.startsWith("(")) {
            // It's a method descriptor
            for (int i = 1; i < descriptor.length(); i++) {
                char ch = descriptor.charAt(i);
                if (ch == ')') {
                    break;
                } else if (ch == 'L' || ch == '[') {
                    // Skip the full class name or array descriptor
                    while (descriptor.charAt(++i) != ';');
                }
                count++;
            }
        }
        // Pop the specified number of abstract types from the output frame stack
        for (int i = 0; i < count; i++) {
            stack.pop();
        }
    } catch (EmptyStackException e) {
        // Handle the case where the stack is empty
        System.err.println("The stack is empty, cannot pop.");
